{
  "info": {
    "title": "UAE Account Information API",
    "description": "## UAE Open Finance Account Information API Specification",
    "version": "v2.2-rc2"
  },
  "servers": [
    {
      "url": "/open-finance/account-information/v2.2"
    }
  ],
  "source_path": "/account-access-consents/{ConsentId}",
  "operations": {
    "patch": {
      "tags": [
        "Bank Data Sharing Consent"
      ],
      "summary": "Patch Consent",
      "description": "Update a Bank Data Sharing Consent Status or Webhook Subscription",
      "operationId": "PatchAccountAccessConsentsConsentId",
      "parameters": [
        {
          "$ref": "#/components/parameters/Authorization"
        },
        {
          "$ref": "#/components/parameters/ConsentId"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        }
      ],
      "requestBody": {
        "description": "Request Body",
        "content": {
          "application/json; charset=utf-8": {
            "schema": {
              "$ref": "#/components/schemas/AEPatchConsent"
            }
          },
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/AEPatchConsent"
            }
          },
          "application/jwt": {
            "schema": {
              "$ref": "#/components/schemas/AEPatchConsentSigned"
            }
          }
        }
      },
      "responses": {
        "204": {
          "$ref": "#/components/responses/204AccountAccessConsentsConsentIdDeleted"
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "415": {
          "$ref": "#/components/responses/415Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "security": [
        {
          "TPPOAuth2Security": [
            "openid",
            "accounts"
          ]
        }
      ]
    }
  }
}

{
  "name": "authorization",
  "in": "header",
  "required": true,
  "description": "An authorization Token as per https://tools.ietf.org/html/rfc6750",
  "schema": {
    "type": "string"
  }
}

{
  "name": "ConsentId",
  "in": "path",
  "description": "ConsentId",
  "required": true,
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-auth-date",
  "required": false,
  "description": "The time when the User last logged in with the TPP. \nAll dates in the HTTP headers are represented as RFC 7231 Full Dates. An example is below: \nSun, 10 Sep 2017 19:43:31 UTC",
  "schema": {
    "type": "string",
    "pattern": "^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \\d{4} \\d{2}:\\d{2}:\\d{2} (GMT|UTC)$"
  }
}

{
  "in": "header",
  "name": "x-fapi-customer-ip-address",
  "required": false,
  "description": "The User's IP address if the User is currently logged in with the TPP.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-interaction-id",
  "required": false,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-customer-user-agent",
  "description": "Indicates the user-agent that the User is using.",
  "required": false,
  "schema": {
    "type": "string"
  }
}

{
  "description": "Patch Bank Data Sharing Consent",
  "type": "object",
  "properties": {
    "Data": {
      "type": "object",
      "description": "Primary data for the resource",
      "required": [
        "Status"
      ],
      "properties": {
        "Status": {
          "$ref": "#/components/schemas/PatchConsentStatus"
        },
        "RevokedBy": {
          "$ref": "#/components/schemas/AERevokedBy"
        }
      },
      "additionalProperties": false
    },
    "Subscription": {
      "$ref": "#/components/schemas/EventNotification"
    }
  },
  "additionalProperties": false
}

{
  "description": "The Revoked status must only be set if the current Consent Status is set to either Authorized or AwaitingAuthorization",
  "type": "string",
  "enum": [
    "Revoked"
  ]
}

{
  "description": "Denotes the Identifier of the revocation.\n\n| Identifier| Description|\n|-----------|------------|\n| LFI | Revoked by LFI without User initiation|\n| TPP | Revoked by TPP without User initiation|\n| LFI.InitiatedByUser | Initiated by User via the LFI|\n| TPP.InitiatedByUser | Initiated by User via the TPP|\n",
  "type": "string",
  "enum": [
    "LFI",
    "TPP",
    "LFI.InitiatedByUser",
    "TPP.InitiatedByUser"
  ]
}

{
  "type": "object",
  "description": "A Webhook Subscription Schema\n",
  "required": [
    "Webhook"
  ],
  "properties": {
    "Webhook": {
      "description": "A Webhook Schema\n",
      "type": "object",
      "properties": {
        "Url": {
          "description": "The TPP Callback URL being registered with the LFI\n",
          "type": "string",
          "example": "https://api.tpp.com/webhook/callbackUrl"
        },
        "IsActive": {
          "description": "The TPP specifying whether the LFI should send (IsActive true) or not send (IsActive false) Webhook Notifications to the TPP's Webhook URL\n",
          "type": "boolean",
          "example": false
        }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false
}

{
  "allOf": [
    {
      "$ref": "#/components/schemas/Jwt"
    },
    {
      "type": "object",
      "properties": {
        "message": {
          "$ref": "#/components/schemas/AEPatchConsent"
        }
      },
      "required": [
        "message"
      ],
      "additionalProperties": false
    }
  ]
}

{
  "description": "[https://www.rfc-editor.org/rfc/rfc7519](https://www.rfc-editor.org/rfc/rfc7519)\n",
  "type": "object",
  "properties": {
    "iss": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1)\n",
      "type": "string"
    },
    "exp": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4)\n",
      "type": "number"
    },
    "nbf": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5)\n",
      "type": "number"
    },
    "aud": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3)\n",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "iat": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6)\n",
      "type": "number"
    }
  },
  "required": [
    "iss",
    "exp",
    "nbf"
  ]
}

{
  "description": "No Content",
  "headers": {
    "x-fapi-interaction-id": {
      "description": "An RFC4122 UID used as a correlation id.",
      "required": true,
      "schema": {
        "type": "string"
      }
    }
  }
}

{
  "description": "Bad request",
  "headers": {
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  },
  "content": {
    "application/json; charset=utf-8": {
      "schema": {
        "$ref": "#/components/schemas/AEError400Response"
      }
    },
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/AEError400Response"
      }
    },
    "application/jwt": {
      "schema": {
        "$ref": "#/components/schemas/AEError400ResponseSigned"
      }
    }
  }
}

{
  "required": true,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  },
  "example": "49df2c2c-6b80-40ee-96a1-71910a248048"
}

{
  "description": "An array of detail error codes, and messages, and URLs to documentation to help remediation.",
  "type": "object",
  "properties": {
    "Errors": {
      "items": {
        "$ref": "#/components/schemas/AEError400"
      },
      "type": "array",
      "minItems": 1
    }
  },
  "required": [
    "Errors"
  ],
  "additionalProperties": false
}

{
  "description": "Error",
  "type": "object",
  "required": [
    "Code",
    "Message"
  ],
  "additionalProperties": false,
  "properties": {
    "Code": {
      "$ref": "#/components/schemas/AEError400Code"
    },
    "Message": {
      "$ref": "#/components/schemas/AEMessage"
    },
    "Path": {
      "description": "Recommended but optional reference to the JSON Path of the field with error, e.g., Data.Initiation.InstructedAmount.Currency",
      "type": "string",
      "minLength": 1,
      "maxLength": 500
    },
    "Url": {
      "description": "URL to help remediate the problem, or provide more information, or to API Reference, or help etc",
      "type": "string"
    }
  }
}

{
  "type": "string",
  "minLength": 1,
  "maxLength": 500,
  "description": "A description of the error that occurred. e.g., 'A mandatory field isn't supplied' or 'RequestedExecutionDateTime must be in future'\nThis field is not standardised"
}

{
  "description": "Error Signed Schema\n",
  "allOf": [
    {
      "$ref": "#/components/schemas/Jwt"
    },
    {
      "type": "object",
      "properties": {
        "message": {
          "$ref": "#/components/schemas/AEError400Response"
        }
      },
      "required": [
        "message"
      ]
    }
  ]
}

{
  "description": "Unauthorized",
  "headers": {
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  }
}

{
  "description": "Forbidden",
  "headers": {
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  },
  "content": {
    "application/json; charset=utf-8": {
      "schema": {
        "$ref": "#/components/schemas/AEError403Response"
      }
    },
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/AEError403Response"
      }
    },
    "application/jwt": {
      "schema": {
        "$ref": "#/components/schemas/AEError403ResponseSigned"
      }
    }
  }
}

{
  "description": "An array of detail error codes, and messages, and URLs to documentation to help remediation.",
  "type": "object",
  "properties": {
    "Errors": {
      "items": {
        "$ref": "#/components/schemas/AEError403"
      },
      "type": "array",
      "minItems": 1
    }
  },
  "required": [
    "Errors"
  ],
  "additionalProperties": false
}

{
  "description": "Error",
  "type": "object",
  "required": [
    "Code",
    "Message"
  ],
  "additionalProperties": false,
  "properties": {
    "Code": {
      "$ref": "#/components/schemas/AEError403Code"
    },
    "Message": {
      "$ref": "#/components/schemas/AEMessage"
    },
    "Path": {
      "description": "Recommended but optional reference to the JSON Path of the field with error, e.g., Data.Initiation.InstructedAmount.Currency",
      "type": "string",
      "minLength": 1,
      "maxLength": 500
    },
    "Url": {
      "description": "URL to help remediate the problem, or provide more information, or to API Reference, or help etc",
      "type": "string"
    }
  }
}

{
  "description": "Error Code. This may either be one of the prescribed Error Code(s) or a namespaced Error Code where the namespace is the system or organisation that has responded with the error, and the code is the code specific to the system or organisation.",
  "type": "string",
  "anyOf": [
    {
      "enum": [
        "AccessToken.InvalidScope",
        "Consent.TransientAccountAccessFailure",
        "Consent.AccountTemporarilyBlocked",
        "Consent.PermanentAccountAccessFailure",
        "GenericRecoverableError",
        "GenericError"
      ]
    },
    {
      "pattern": "^[A-Za-z]+\\.[A-Za-z0-9]+$"
    }
  ]
}

{
  "description": "Error Signed Schema\n",
  "allOf": [
    {
      "$ref": "#/components/schemas/Jwt"
    },
    {
      "type": "object",
      "properties": {
        "message": {
          "$ref": "#/components/schemas/AEError403Response"
        }
      },
      "required": [
        "message"
      ]
    }
  ]
}

{
  "description": "Method Not Allowed",
  "headers": {
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  }
}

{
  "description": "Not Acceptable",
  "headers": {
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  }
}

{
  "description": "Unsupported Media Type",
  "headers": {
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  }
}

{
  "description": "Too Many Requests",
  "headers": {
    "Retry-After": {
      "description": "Number in seconds to wait",
      "schema": {
        "type": "integer"
      }
    },
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  }
}

{
  "description": "Internal Server Error",
  "headers": {
    "x-fapi-interaction-id": {
      "$ref": "#/components/headers/x-fapi-interaction-id"
    }
  },
  "content": {
    "application/json; charset=utf-8": {
      "schema": {
        "$ref": "#/components/schemas/AEError500Response"
      }
    },
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/AEError500Response"
      }
    },
    "application/jwt": {
      "schema": {
        "$ref": "#/components/schemas/AEError500ResponseSigned"
      }
    }
  }
}

{
  "description": "An array of detail error codes, and messages, and URLs to documentation to help remediation.",
  "type": "object",
  "properties": {
    "Errors": {
      "items": {
        "$ref": "#/components/schemas/AEError500"
      },
      "type": "array",
      "minItems": 1
    }
  },
  "required": [
    "Errors"
  ],
  "additionalProperties": false
}

{
  "description": "Error",
  "type": "object",
  "required": [
    "Code",
    "Message"
  ],
  "additionalProperties": false,
  "properties": {
    "Code": {
      "$ref": "#/components/schemas/AEError500Code"
    },
    "Message": {
      "$ref": "#/components/schemas/AEMessage"
    },
    "Path": {
      "description": "Recommended but optional reference to the JSON Path of the field with error, e.g., Data.Initiation.InstructedAmount.Currency",
      "type": "string",
      "minLength": 1,
      "maxLength": 500
    },
    "Url": {
      "description": "URL to help remediate the problem, or provide more information, or to API Reference, or help etc",
      "type": "string"
    }
  }
}

{
  "description": "Error Code. This may either be one of the prescribed Error Code(s) or a namespaced Error Code where the namespace is the system or organisation that has responded with the error, and the code is the code specific to the system or organisation.",
  "type": "string",
  "anyOf": [
    {
      "enum": [
        "GenericRecoverableError",
        "GenericError"
      ]
    },
    {
      "pattern": "^[A-Za-z]+\\.[A-Za-z0-9]+$"
    }
  ]
}

{
  "description": "Error Signed Schema\n",
  "allOf": [
    {
      "$ref": "#/components/schemas/Jwt"
    },
    {
      "type": "object",
      "properties": {
        "message": {
          "$ref": "#/components/schemas/AEError500Response"
        }
      },
      "required": [
        "message"
      ]
    }
  ]
}
